type LineItem {
    name: Text;
    qty: Int;
    price: Real;
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"order\":1042,\"customer\":\"Ada\",\"lines\":[{\"name\":\"pen\",\"qty\":3,\"price\":1.5},{\"name\":\"notebook\",\"qty\":2,\"price\":4.25},{\"name\":\"stapler\",\"qty\":1,\"price\":12.0}]}");
    let root: ToonNode = toon_root(doc);
    let lines: ToonNode = toon_key(root, "lines");
    let items: LineItem[] = [];
    loop line in lines {
        items = items + [new LineItem {
            name: toon_get_text(line, "name"),
            qty: toon_get_int(line, "qty"),
            price: toon_get_real(line, "price")
        }];
    }
    let subtotal: Real = 0.0;
    fx { println("order ", toon_get_int(root, "order"), " for ", toon_get_text(root, "customer")); }
    loop it in items {
        let cost: Real = it.qty * it.price;
        subtotal = subtotal + cost;
        fx { println(it.name, " x", it.qty, " = ", formatfloat(cost, 2)); }
    }
    let tax: Real = subtotal * 0.08;
    fx {
        println("subtotal ", formatfloat(subtotal, 2));
        println("tax ", formatfloat(tax, 2));
        println("total ", formatfloat(subtotal + tax, 2));
    }
    toon_close(doc);
    ret;
}

@pre score >= 0 && score <= 100
fn letter(score: Int) -> Text {
    if score >= 90 { ret "A"; }
    if score >= 80 { ret "B"; }
    if score >= 70 { ret "C"; }
    if score >= 60 { ret "D"; }
    ret "F";
}

@pre toon_len(scores) > 0
fn mean(scores: ToonNode) -> Real {
    let sum: Int = 0;
    loop s in scores {
        sum = sum + toon_int_value(s);
    }
    ret sum * 1.0 / toon_len(scores);
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"course\":\"Algebra\",\"scores\":[88,92,75,100,64]}");
    let root: ToonNode = toon_root(doc);
    let scores: ToonNode = toon_key(root, "scores");
    fx {
        println(toon_get_text(root, "course"));
        loop s in scores {
            let v: Int = toon_int_value(s);
            println(v, " ", letter(v));
        }
        println("mean ", mean(scores):0:2);
    }
    toon_close(doc);
    ret;
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"sensors\":[{\"id\":\"t1\",\"kind\":\"temp\",\"value\":71.5},{\"id\":\"h1\",\"kind\":\"humidity\",\"value\":38},{\"id\":\"t2\",\"kind\":\"temp\",\"value\":88.25}],\"limits\":{\"temp\":80,\"humidity\":60}}");
    let root: ToonNode = toon_root(doc);
    let sensors: ToonNode = toon_key(root, "sensors");
    let limits: ToonNode = toon_key(root, "limits");
    let alerts: Int = 0;
    loop i in 0..toon_len(sensors) {
        let s: ToonNode = toon_at(sensors, i);
        let kind: Text = toon_get_text(s, "kind");
        let value: Real = toon_get_real(s, "value");
        let limit: Real = toon_get_real(limits, kind);
        let head: Text = toon_get_text(s, "id") + " " + kind + " " + formatfloat(value, 2);
        if value > limit {
            alerts = alerts + 1;
            fx { println(head, " ALERT over by ", formatfloat(value - limit, 2)); }
        } else {
            fx { println(head, " ok"); }
        }
    }
    fx { println("alerts=", alerts); }
    toon_close(doc);
    ret;
}

fn cell(grid: ToonNode, r: Int, c: Int) -> Int {
    ret toon_int_value(toon_at(toon_at(grid, r), c));
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"name\":\"magic\",\"grid\":[[2,7,6],[9,5,1],[4,3,8]]}");
    let grid: ToonNode = toon_key(toon_root(doc), "grid");
    let n: Int = toon_len(grid);
    let sums: Int[] = [];
    let rows: Text = "rows:";
    let cols: Text = "cols:";
    loop r in 0..n {
        let s: Int = 0;
        loop c in 0..n { s = s + cell(grid, r, c); }
        sums = sums + [s];
        rows = rows + " " + int_to_text(s);
    }
    loop c in 0..n {
        let s: Int = 0;
        loop r in 0..n { s = s + cell(grid, r, c); }
        sums = sums + [s];
        cols = cols + " " + int_to_text(s);
    }
    let diag: Int = 0;
    let anti: Int = 0;
    loop k in 0..n {
        diag = diag + cell(grid, k, k);
        anti = anti + cell(grid, k, n - 1 - k);
    }
    sums = sums + [diag, anti];
    let magic: Bool = true;
    loop v in sums {
        if v != sums[0] { magic = false; }
    }
    fx {
        println(rows);
        println(cols);
        println("diagonals: ", diag, " ", anti);
        println("magic=", magic);
    }
    toon_close(doc);
    ret;
}

