    let hi: Int = toon_get_int(root, "range.full_mv");
    let devices: ToonNode = toon_key(root, "devices");
    loop i in 0..toon_len(devices) {
        let d: ToonNode = toon_at(devices, i);
        let pct: Int = percent(toon_get_int(d, "mv"), lo, hi);
        let flag: Text = if pct < 20 { " LOW" } else { "" };
        fx { println(toon_get_text(d, "name"), " ", pct, "%", flag); }
