fn seconds(node: ToonNode) -> Real {
    if toon_is_int(node) {
        ret toon_int_value(node) * 1.0;
    }
    ret toon_real_value(node);
}

fn main() -> Void {
    if !has_toon() {
        fx { println("cannot read splits"); }
        ret;
    }

    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("splits.json");
    }
    let splits: ToonNode = toon_root(doc);
    let n: Int = toon_len(splits);
    let half: Int = n div 2;

    let total: Real = 0.0;
    let firstHalf: Real = 0.0;
    let best: Real = seconds(toon_at(splits, 0));
    let bestAt: Int = 0;

    loop i in 0..n {
        let s: Real = seconds(toon_at(splits, i));
        total = total + s;
        if i < half {
            firstHalf = firstHalf + s;
        }
        if s < best {
            best = s;
            bestAt = i;
        }
    }
    let secondHalf: Real = total - firstHalf;

    fx {
        println("splits: ", n);
        println("total: ", total:0:2);
        println("fastest: #", bestAt + 1, " ", best:0:2);
        println("average: ", (total / n):0:2);
        println("second half slower by ", (secondHalf - firstHalf):0:2);
    }
    toon_close(doc);
    ret;
}

fn main() -> Void {
    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("orders.json");
    }
    let orders: ToonNode = toon_root(doc);
    let coupons: Int = 0;
    let discounted: Int = 0;

    loop i in 0..toon_len(orders) {
        let order: ToonNode = toon_at(orders, i);
        let id: Text = toon_get_text(order, "id");
        let subtotal: Int = toon_get_int(order, "subtotal");
        let coupon: ToonNode = toon_key_or(order, "coupon", toon_null());

        if toon_is_null(coupon) {
            fx {
                println(id, " no coupon -> ", subtotal);
            }
        } else {
            let off: Int = subtotal * toon_get_int_or(coupon, "percent", 0) div 100;
            coupons = coupons + 1;
            discounted = discounted + off;
            fx {
                println(id, " ", toon_get_text(coupon, "code"), " -", off, " -> ", subtotal - off);
            }
        }
    }

    fx {
        println("coupons=", coupons, " discount=", discounted);
    }
    toon_close(doc);
    ret;
}

