const DEFAULT_ALERT: Int = 80;

fn main() -> Void {
    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("hosts.json");
    }
    let hosts: ToonNode = toon_root(doc);
    let alerts: Int = 0;

    loop i in 0..toon_len(hosts) {
        let h: ToonNode = toon_at(hosts, i);
        let name: Text = toon_get_text(h, "host");
        let disk: ToonNode = toon_key_or(h, "disk", toon_null());

        if toon_is_null(disk) {
            fx { println(name, " no disk data"); }
            continue;
        }

        let pct: Int = toon_get_int(disk, "used_gb") * 100 div toon_get_int(disk, "size_gb");
        let threshold: Int = toon_get_int_or(disk, "alert_pct", DEFAULT_ALERT);
        if pct >= threshold {
            alerts = alerts + 1;
            fx { println(name, " ", pct, "% ALERT"); }
        } else {
            fx { println(name, " ", pct, "% ok"); }
        }
    }

    fx {
        println("alerts: ", alerts);
    }
    toon_close(doc);
    ret;
}

fn main() -> Void {
    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("parcel.json");
    }
    let root: ToonNode = toon_root(doc);
    let pts: ToonNode = toon_key(root, "vertices");
    let n: Int = toon_len(pts);

    let minX: Int = toon_int_value(toon_at(toon_at(pts, 0), 0));
    let maxX: Int = minX;
    let minY: Int = toon_int_value(toon_at(toon_at(pts, 0), 1));
    let maxY: Int = minY;
    let twice: Int = 0;

    loop i in 0..n {
        let p: ToonNode = toon_at(pts, i);
        let q: ToonNode = toon_at(pts, (i + 1) % n);
        let x: Int = toon_int_value(toon_at(p, 0));
        let y: Int = toon_int_value(toon_at(p, 1));
        minX = min(minX, x);
        maxX = max(maxX, x);
        minY = min(minY, y);
        maxY = max(maxY, y);
        twice = twice + x * toon_int_value(toon_at(q, 1)) - toon_int_value(toon_at(q, 0)) * y;
    }

    let area: Real = abs(twice) / 2.0;
    fx {
        println(toon_get_text(root, "parcel"));
        println("vertices: ", n);
        println("bbox: ", minX, ",", minY, " to ", maxX, ",", maxY);
        println("area: ", area:0:1, " m2");
    }
    toon_close(doc);
    ret;
}

fn indexOf(codes: Text[], code: Text) -> Int {
    loop i in 0..length(codes) {
        if codes[i] == code {
            ret i;
        }
    }
    ret -1;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("league data unavailable"); }
        ret;
    }

    let teamDoc: ToonDoc;
    let matchDoc: ToonDoc;
    fx {
        teamDoc = toon_parse_file("teams.json");
        matchDoc = toon_parse_file("matches.json");
    }

    let teams: ToonNode = toon_root(teamDoc);
    let codes: Text[] = [];
    let names: Text[] = [];
    let points: Int[] = [];
    loop t in teams {
        codes = codes + [toon_get_text(t, "code")];
        names = names + [toon_get_text(t, "name")];
        points = points + [0];
    }

    let root: ToonNode = toon_root(matchDoc);
    let matches: ToonNode = toon_key(root, "matches");
    loop i in 0..toon_len(matches) {
        let m: ToonNode = toon_at(matches, i);
        let home: Int = indexOf(codes, toon_get_text(m, "home"));
        let away: Int = indexOf(codes, toon_get_text(m, "away"));
        let hg: Int = toon_get_int(m, "hg");
        let ag: Int = toon_get_int(m, "ag");
        if hg > ag {
            points[home] = points[home] + 3;
        } else if ag > hg {
            points[away] = points[away] + 3;
        } else {
            points[home] = points[home] + 1;
            points[away] = points[away] + 1;
        }
        toon_free(m);
    }

    let best: Int = 0;
    loop i in 1..length(points) {
        if points[i] > points[best] {
            best = i;
        }
    }

    fx {
        println(toon_get_text(root, "season"), " season, ", toon_len(matches), " matches");
        loop i in 0..length(names) {
            println(names[i], " ", points[i]);
        }
        println("leader: ", names[best]);
    }
    toon_close(teamDoc);
    toon_close(matchDoc);
    ret;
}

