fn pad3(n: Int) -> Text {
    if n < 10 {
        ret "00" + int_to_text(n);
    }
    if n < 100 {
        ret "0" + int_to_text(n);
    }
    ret int_to_text(n);
}

fn main() -> Void {
    let events: Text[] = ["boot", "load", "serve"];
    let out: MStream = mstreamcreate();
    loop i in 0..length(events) {
        appendText(out, pad3(i + 1));
        mstreamappendbyte(out, ord(" "));
        appendText(out, events[i]);
        mstreamappendbyte(out, 10);
    }
    let original: Text = mstreambuffer(out);
    let back: MStream = mstreamcreate();
    fx {
        mstreamsavetofile(out, "events.log");
        let ok: Bool = mstreamloadfromfile(back, "events.log");
        let loaded: Text = mstreambuffer(back);
        println("loaded=", ok);
        print(loaded);
        println("match=", loaded == original);
    }
    mstreamfree(out);
    mstreamfree(back);
    ret;
}

fn hexOf(text: Text) -> Text {
    let digits: Text = "0123456789ABCDEF";
    let ms: MStream = mstreamcreate();
    loop ch in text {
        let b: Int = ord(ch);
        mstreamappendbyte(ms, ord(digits[b div 16]));
        mstreamappendbyte(ms, ord(digits[b % 16]));
    }
    let encoded: Text = mstreambuffer(ms);
    mstreamfree(ms);
    ret encoded;
}

