fn jsonQuote(raw: Text) -> Text {
    let ms: MStream = mstreamcreate();
    mstreamappendbyte(ms, ord("\""));
    loop ch in raw {
        let b: Int = ord(ch);
        if b == 34 {
            appendText(ms, "\\\"");
        } else if b == 92 {
            appendText(ms, "\\\\");
        } else if b == 10 {
            appendText(ms, "\\n");
        } else if b == 9 {
            appendText(ms, "\\t");
        } else {
            mstreamappendbyte(ms, b);
        }
    }
    mstreamappendbyte(ms, ord("\""));
    let quoted: Text = mstreambuffer(ms);
    mstreamfree(ms);
    ret quoted;
}

fn main() -> Void {
    let raw: Text = "say \"hi\" C:\\tmp\nend";
    let quoted: Text = jsonQuote(raw);
    fx {
        println(quoted);
        println("in=", string_len(raw), " out=", string_len(quoted));
    }
    ret;
}

fn titleCase(s: Text) -> Text {
    let ms: MStream = mstreamcreate();
    let atWordStart: Bool = true;
    loop ch in s {
        let b: Int = ord(ch);
        if b == 32 {
            atWordStart = true;
            mstreamappendbyte(ms, b);
        } else {
            if atWordStart && b >= 97 && b <= 122 {
                mstreamappendbyte(ms, b - 32);
            } else {
                mstreamappendbyte(ms, b);
            }
            atWordStart = false;
        }
    }
    let result: Text = mstreambuffer(ms);
    mstreamfree(ms);
    ret result;
}

