fn main() -> Void {
    let chart: Text[] = ["LL~~~L", "L~~LLL", "~~~~L~", "LL~~~~", "~L~LL~"];
    let rows: Int = length(chart);
    let cols: Int = length(chart[0]);
    let land: Bool[][] = [];
    let seen: Bool[][] = [];
    loop line in chart {
        let landRow: Bool[] = [];
        let seenRow: Bool[] = [];
        loop ch in line {
            landRow = landRow + [ch == "L"];
            seenRow = seenRow + [false];
        }
        land = land + [landRow];
        seen = seen + [seenRow];
    }
    let dr: Int[] = [-1, 1, 0, 0];
    let dc: Int[] = [0, 0, -1, 1];
    let sizes: Int[] = [];
    loop r in 0..rows {
        loop c in 0..cols {
            if land[r][c] && !seen[r][c] {
                let stack: Int[] = [r * cols + c];
                seen[r][c] = true;
                let size: Int = 0;
                loop length(stack) > 0 {
                    let cell: Int = stack[length(stack) - 1];
                    setlength(stack, length(stack) - 1);
                    size = size + 1;
                    let y: Int = cell div cols;
                    let x: Int = cell % cols;
                    loop d in 0..4 {
                        let ny: Int = y + dr[d];
                        let nx: Int = x + dc[d];
                        if ny >= 0 && ny < rows && nx >= 0 && nx < cols {
                            if land[ny][nx] && !seen[ny][nx] {
                                seen[ny][nx] = true;
                                stack = stack + [ny * cols + nx];
                            }
                        }
                    }
                }
                sizes = sizes + [size];
            }
        }
    }
    let largest: Int = 0;
    loop s in sizes {
        largest = max(largest, s);
    }
    fx {
        println("islands: ", length(sizes));
        print("sizes:");
        loop s in sizes {
            print(" ", s);
        }
        println("");
        println("largest: ", largest);
    }
    ret;
}

