    let tri: Int[][] = [[5], [9, 6], [4, 6, 8], [0, 7, 1, 5], [8, 3, 1, 1, 2]];
    let best: Int[][] = [];
    loop r in 0..length(tri) {
        let row: Int[] = [];
        loop k in 0..length(tri[r]) {
            let v: Int = tri[r][k];
            if r == 0 {
                row = row + [v];
            } else if k == 0 {
                row = row + [v + best[r - 1][0]];
            } else if k == r {
                row = row + [v + best[r - 1][k - 1]];
            } else {
                row = row + [v + min(best[r - 1][k - 1], best[r - 1][k])];
            }
        }
        best = best + [row];
    }

    let last: Int = length(tri) - 1;
    let k: Int = 0;
    loop i in 1..length(best[last]) {
        if best[last][i] < best[last][k] {
            k = i;
        }
    }
    let total: Int = best[last][k];
    let path: Int[] = [tri[last][k]];
    loop r in last..0 step -1 {
        if k == r {
            k = k - 1;
        } else if k > 0 && best[r - 1][k - 1] <= best[r - 1][k] {
            k = k - 1;
        }
        path = [tri[r - 1][k]] + path;
    }
    fx {
        println("total: ", total);
        print("path: ", path[0]);
        loop i in 1..length(path) {
            print(" -> ", path[i]);
        }
        println("");
    }
    ret;
}

