    loop i in 1..n + 1 {
        let w: Int = minutes[i - 1];
        let row: Bool[] = [];
        loop s in 0..limit + 1 {
            if can[i - 1][s] {
                row = row + [true];
            } else if s >= w {
                row = row + [can[i - 1][s - w]];
            } else {
                row = row + [false];
            }
        }
