@pure
fn check(m: Int[][]) -> Text {
    let n: Int = length(m);
    let target: Int = 0;
    loop v in m[0] {
        target = target + v;
    }
    let mainDiag: Int = 0;
    let antiDiag: Int = 0;
    loop i in 0..n {
        mainDiag = mainDiag + m[i][i];
        antiDiag = antiDiag + m[i][n - 1 - i];
    }
    let problem: Text = "";
    loop r in 0..n {
        let sum: Int = 0;
        loop c in 0..n {
            sum = sum + m[r][c];
        }
        if sum != target && problem == "" {
            problem = "row " + int_to_text(r + 1) + " sums to " + int_to_text(sum);
        }
    }
    loop c in 0..n {
        let sum: Int = 0;
        loop r in 0..n {
            sum = sum + m[r][c];
        }
        if sum != target && problem == "" {
            problem = "column " + int_to_text(c + 1) + " sums to " + int_to_text(sum);
        }
    }
    let head: Text = "diagonals " + int_to_text(mainDiag) + " and " + int_to_text(antiDiag) + ", ";
    if problem != "" {
        ret head + "not magic: " + problem;
    } else if mainDiag != target {
        ret head + "not magic: main diagonal sums to " + int_to_text(mainDiag);
    } else if antiDiag != target {
        ret head + "not magic: anti-diagonal sums to " + int_to_text(antiDiag);
    } else {
        ret head + "magic, constant " + int_to_text(target);
    }
}

