@pure
fn fits(grid: Text[][], word: Text, r: Int, c: Int, dr: Int, dc: Int) -> Bool {
    loop k in 0..length(word) {
        let y: Int = r + dr * k;
        let x: Int = c + dc * k;
        if y < 0 || y >= length(grid) || x < 0 || x >= length(grid[y]) {
            ret false;
        }
        if grid[y][x] != word[k] {
            ret false;
        }
    }
    ret true;
}

