type SortRun {
    items: Text[] = [];
    swaps: Int = 0;
}

@pure
fn gnomeSort(labels: Text[]) -> SortRun {
    let run: SortRun = new SortRun { items: labels };
    let i: Int = 1;
    loop i < length(run.items) {
        if i == 0 || run.items[i - 1] <= run.items[i] {
            i = i + 1;
        } else {
            let tmp: Text = run.items[i - 1];
            run.items[i - 1] = run.items[i];
            run.items[i] = tmp;
            run.swaps = run.swaps + 1;
            i = i - 1;
        }
    }
    ret run;
}

fn main() -> Void {
    let shelf: Text[] = ["delta", "alpha", "echo", "bravo", "charlie", "alpha"];
    let run: SortRun = gnomeSort(shelf);
    fx {
        loop i in 0..length(run.items) {
            if i > 0 {
                print(", ");
            }
            print(run.items[i]);
        }
        println("");
        println("swaps=", run.swaps);
    }
    ret;
}

