@pure
fn byTime(field: Runner[]) -> Runner[] {
    loop i in 1..length(field) {
        let cur: Runner = field[i];
        let j: Int = i - 1;
        loop j >= 0 && field[j].seconds > cur.seconds {
            field[j + 1] = field[j];
            j = j - 1;
        }
        field[j + 1] = cur;
    }
    ret field;
}

@pure
fn clock(seconds: Int) -> Text {
    let secs: Int = seconds % 60;
    let pad: Text = if secs < 10 { "0" } else { "" };
    ret int_to_text(seconds div 60) + ":" + pad + int_to_text(secs);
}

