type Split {
    below: Int[] = [];
    atOrAbove: Int[] = [];
}

fn partitionInto(out: Split, readings: Int[], limit: Int) -> Void {
    loop r in readings {
        if r < limit {
            out.below = out.below + [r];
        } else {
            out.atOrAbove = out.atOrAbove + [r];
        }
    }
    ret;
}

