        loop i in 0..length(unique) {
            if i > 0 {
                print(", ");
            }
            print(unique[i]);
        }
        println("");
        println("removed ", length(tags) - length(unique));
    }
    ret;
}

@pure
fn rotateRight(xs: Int[], k: Int) -> Int[] {
    let n: Int = length(xs);
    if n == 0 {
        ret xs;
    }
    let shift: Int = (k % n + n) % n;
    ret xs[n - shift..n] + xs[0..n - shift];
}

