    let targets: Int[] = [23, 30, 28];
    fx {
        loop t in targets {
            println("target ", t, ":", pairsFor(prices, t));
        }
    }
    ret;
}

@pure
fn sortedCopy(xs: Int[]) -> Int[] {
    loop i in 1..length(xs) {
        let v: Int = xs[i];
        let j: Int = i - 1;
        loop j >= 0 && xs[j] > v {
            xs[j + 1] = xs[j];
            j = j - 1;
        }
        xs[j + 1] = v;
    }
    ret xs;
}

@pre length(xs) > 0
@pure
fn median(xs: Int[]) -> Real {
    let s: Int[] = sortedCopy(xs);
    let n: Int = length(s);
    let mid: Int = n div 2;
    if n % 2 == 1 {
        ret real(s[mid]);
    }
    ret (s[mid - 1] + s[mid]) / 2.0;
}

