    let keys: Text[] = [];
    let counts: Int[] = [];
    loop w in words {
        let at: Int = -1;
        loop i in 0..length(keys) {
            if keys[i] == w {
                at = i;
                break;
            }
        }
        if at >= 0 {
            counts[at] = counts[at] + 1;
        } else {
            keys = keys + [w];
            counts = counts + [1];
        }
    }
    loop i in 1..length(counts) {
        let c: Int = counts[i];
        let k: Text = keys[i];
        let j: Int = i - 1;
        loop j >= 0 && counts[j] < c {
            counts[j + 1] = counts[j];
            keys[j + 1] = keys[j];
            j = j - 1;
        }
        counts[j + 1] = c;
        keys[j + 1] = k;
    }
    fx {
        loop i in 0..length(keys) {
            println(keys[i], " ", counts[i]);
        }
    }
    ret;
}

@pure
fn mergeSorted(a: Int[], b: Int[]) -> Int[] {
    let out: Int[] = [];
    let i: Int = 0;
    let j: Int = 0;
    loop i < length(a) && j < length(b) {
        if a[i] <= b[j] {
            out = out + [a[i]];
            i = i + 1;
        } else {
            out = out + [b[j]];
            j = j + 1;
        }
    }
    ret out + a[i..length(a)] + b[j..length(b)];
}

