@pure
fn majorityOf(votes: Int[]) -> Int {
    let candidate: Int = -1;
    let lead: Int = 0;
    loop v in votes {
        if lead == 0 {
            candidate = v;
            lead = 1;
        } else if v == candidate {
            lead = lead + 1;
        } else {
            lead = lead - 1;
        }
    }
    let hits: Int = 0;
    loop v in votes {
        if v == candidate {
            hits = hits + 1;
        }
    }
    if hits * 2 > length(votes) {
        ret candidate;
    }
    ret -1;
}

fn report(name: Text, votes: Int[]) -> Void {
    let winner: Int = majorityOf(votes);
    fx {
        if winner >= 0 {
            println("poll ", name, ": ", winner, " wins");
        } else {
            println("poll ", name, ": no majority");
        }
    }
    ret;
}

