@pure
fn nextGreater(xs: Int[]) -> Int[] {
    let n: Int = length(xs);
    let answer: Int[] = [];
    setlength(answer, n);
    let stack: Int[] = [];
    loop i in n - 1..-1 step -1 {
        loop length(stack) > 0 && stack[length(stack) - 1] <= xs[i] {
            stack = stack[0..length(stack) - 1];
        }
        answer[i] = if length(stack) > 0 { stack[length(stack) - 1] } else { -1 };
        stack = stack + [xs[i]];
    }
    ret answer;
}

