fn properDivisorSum(n: Int) -> Int {
    if n < 2 {
        ret 0;
    }
    let total: Int = 1;
    let d: Int = 2;
    loop d * d <= n {
        if n % d == 0 {
            let partner: Int = n div d;
            total = total + d;
            if partner != d {
                total = total + partner;
            }
        }
        d = d + 1;
    }
    ret total;
}

fn main() -> Void {
    let numbers: Int[] = [1, 6, 12, 28, 35, 496, 945, 8128, 100];
    fx {
        loop n in numbers {
            let s: Int = properDivisorSum(n);
            let kind: Text = "";
            if s == n {
                kind = "perfect";
            } else if s > n {
                kind = "abundant";
            } else {
                kind = "deficient";
            }
            println(n, " ", kind, " (divisor sum ", s, ")");
        }
    }
    ret;
}

fn digitSum(n: Int) -> Int {
    let rest: Int = n;
    let total: Int = 0;
    loop rest > 0 {
        total = total + rest % 10;
        rest = rest div 10;
    }
    ret total;
}

fn main() -> Void {
