fn taxFor(income: Int) -> Int {
    let tax: Int = 0;
    if income <= 10000 {
        tax = 0;
    } else if income <= 40000 {
        tax = (income - 10000) * 10 div 100;
    } else if income <= 90000 {
        tax = 3000 + (income - 40000) * 20 div 100;
    } else {
        tax = 13000 + (income - 90000) * 30 div 100;
    }
    ret tax;
}

