    let prefixes: Text[] = ["030640615", "097522980"];
    fx {
        loop code in codes {
            println(code, " ", checkIsbn(code));
        }
        loop prefix in prefixes {
            println("check digit for ", prefix, ": ", checkDigit(prefix));
        }
    }
    ret;
}

fn twoDigits(n: Int) -> Text {
    if n < 10 {
