            let value: Int = n;
            let additions: Int = 0;
            let found: Bool = false;
            loop additions < limit {
                value = value + reverseDigits(value);
                additions = additions + 1;
                if value == reverseDigits(value) {
                    found = true;
                    break;
                }
            }
            if found {
                println(n, " -> ", value, " (additions=", additions, ")");
            } else {
                println(n, ": no palindrome in ", limit, " additions");
            }
        }
    }
    ret;
}

fn diagonalSum(size: Int) -> Int {
    let total: Int = 1;
    loop side in 3..size + 1 step 2 {
        let corner: Int = side * side;
        let gap: Int = side - 1;
        total = total + 4 * corner - 6 * gap;
    }
    ret total;
}

