}

fn columnNumber(name: Text) -> Int {
    let value: Int = 0;
    loop ch in name {
        value = value * 26 + (ord(ch) - ord("A") + 1);
    }
    ret value;
}

fn columnName(n: Int) -> Text {
    let rest: Int = n;
    let out: Text = "";
    loop rest > 0 {
        rest = rest - 1;
        out = chr(ord("A") + rest % 26) + out;
        rest = rest div 26;
    }
    ret out;
}

